CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, source TEXT NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', severity TEXT NOT NULL, labels JSONB NOT NULL DEFAULT '{}'::jsonb, value DOUBLE PRECISION NOT NULL DEFAULT 0, occurred_at TIMESTAMPTZ NOT NULL, received_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_events_received_at ON events(received_at DESC);
CREATE INDEX IF NOT EXISTS idx_events_source_name ON events(source,name);
CREATE TABLE IF NOT EXISTS rules (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', enabled BOOLEAN NOT NULL DEFAULT TRUE, source TEXT NOT NULL DEFAULT '', event_name TEXT NOT NULL, match_labels JSONB NOT NULL DEFAULT '{}'::jsonb, severity TEXT NOT NULL DEFAULT '', threshold DOUBLE PRECISION, window_seconds BIGINT NOT NULL DEFAULT 0, escalation_minutes INTEGER NOT NULL DEFAULT 0, channels JSONB NOT NULL DEFAULT '["webhook"]'::jsonb, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_rules_enabled_name ON rules(enabled,event_name);
CREATE TABLE IF NOT EXISTS alerts (id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL UNIQUE, rule_id TEXT NOT NULL REFERENCES rules(id), title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', source TEXT NOT NULL, severity TEXT NOT NULL, labels JSONB NOT NULL DEFAULT '{}'::jsonb, status TEXT NOT NULL CHECK(status IN ('open','acknowledged','resolved','suppressed')), count INTEGER NOT NULL DEFAULT 1, first_seen TIMESTAMPTZ NOT NULL, last_seen TIMESTAMPTZ NOT NULL, acknowledged_at TIMESTAMPTZ, resolved_at TIMESTAMPTZ, silence_id TEXT);
CREATE INDEX IF NOT EXISTS idx_alerts_status_seen ON alerts(status,last_seen DESC);
CREATE TABLE IF NOT EXISTS silence_windows (id TEXT PRIMARY KEY, created_by TEXT NOT NULL DEFAULT '', comment TEXT NOT NULL DEFAULT '', match_labels JSONB NOT NULL DEFAULT '{}'::jsonb, starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_silence_window ON silence_windows(starts_at,ends_at);
CREATE TABLE IF NOT EXISTS duty_schedules (id TEXT PRIMARY KEY, name TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'UTC', members JSONB NOT NULL DEFAULT '[]'::jsonb, start_hour INTEGER NOT NULL DEFAULT 0, end_hour INTEGER NOT NULL DEFAULT 24, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS notification_channels (id TEXT PRIMARY KEY, name TEXT NOT NULL, channel_type TEXT NOT NULL CHECK(channel_type IN ('webhook','email','sms')), target TEXT NOT NULL, secret_ref TEXT NOT NULL DEFAULT '', enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS notification_records (id TEXT PRIMARY KEY, alert_id TEXT NOT NULL REFERENCES alerts(id), rule_id TEXT NOT NULL REFERENCES rules(id), channel TEXT NOT NULL, target TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','sent','failed','dead_letter')), attempts INTEGER NOT NULL DEFAULT 0, error TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL, sent_at TIMESTAMPTZ, next_attempt_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_notifications_alert ON notification_records(alert_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_notifications_retry ON notification_records(status,next_attempt_at);
